<script setup lang="ts">import{reactive,shallowRef,watch}from'vue';const open=defineModel<boolean>({required:true});const emit=defineEmits<{submit:[payload:{sourceType:'LOCAL_GIT'|'REMOTE_GIT'|'GITLAB'|'ZIP';name:string;path:string;url:string;branch:string;file:File|null}]}>();const form=reactive({sourceType:'LOCAL_GIT'as'LOCAL_GIT'|'REMOTE_GIT'|'GITLAB'|'ZIP',name:'',path:'',url:'',branch:''});const file=shallowRef<File|null>(null);watch(open,o=>{if(o){Object.assign(form,{sourceType:'LOCAL_GIT',name:'',path:'',url:'',branch:''});file.value=null}});function choose(upload:{raw?:File}){file.value=upload.raw??null}function submit(){if(!form.name.trim())return;emit('submit',{...form,name:form.name.trim(),file:file.value})}</script>
<template><el-dialog v-model="open" title="接入代码仓库" width="560"><el-form label-position="top"><el-form-item label="来源类型"><el-radio-group v-model="form.sourceType"><el-radio-button value="LOCAL_GIT">本地 Git</el-radio-button><el-radio-button value="REMOTE_GIT">远程 Git</el-radio-button><el-radio-button value="GITLAB">GitLab</el-radio-button><el-radio-button value="ZIP">ZIP</el-radio-button></el-radio-group></el-form-item><el-form-item label="仓库名称" required><el-input v-model="form.name" maxlength="100"/></el-form-item><el-form-item v-if="form.sourceType==='LOCAL_GIT'" label="服务端本地 Git 路径" required><el-input v-model="form.path" placeholder="C:\workspace\project"/></el-form-item><template v-else-if="form.sourceType!=='ZIP'"><el-form-item label="HTTPS Git 地址" required><el-input v-model="form.url" placeholder="https://git.example.com/group/project.git"/></el-form-item><el-form-item label="分支（留空使用默认分支）"><el-input v-model="form.branch"/></el-form-item><el-alert title="私有仓库请先为运行服务的系统账号配置 Git 凭据；请求中不接受内嵌用户名或 Token。" type="info" :closable="false"/></template><el-form-item v-else label="ZIP 文件" required><el-upload :auto-upload="false" :limit="1" accept=".zip,application/zip" :on-change="choose"><el-button>选择 ZIP</el-button></el-upload></el-form-item></el-form><template #footer><el-button @click="open=false">取消</el-button><el-button type="primary" @click="submit">验证并导入</el-button></template></el-dialog></template>
